const daily = $json;
if (!daily.date || !daily.room) throw new Error('Daily report response is missing room or date');
const start = new Date(`${daily.date}T00:00:00+07:00`).toISOString();
const end = new Date(`${daily.date}T23:59:59.999+07:00`).toISOString();
const recommendation = daily.devicesWithIssues > 0
  ? `Kiểm tra ${daily.devicesWithIssues}/${daily.totalDevices} thiết bị đang ngoại tuyến.`
  : daily.totalIncidents > 0
    ? `Theo dõi ${daily.openIncidents} sự cố đang mở và xác nhận các sự cố đã xử lý.`
    : 'Không ghi nhận sự cố hoặc thiết bị ngoại tuyến trong ngày.';
return { json: { report_type: 'DAILY', room: daily.room, period_start: start, period_end: end, summary: { date: daily.date, totalIncidents: daily.totalIncidents, openIncidents: daily.openIncidents, resolvedIncidents: daily.resolvedIncidents, incidentsBySeverity: daily.incidentsBySeverity, totalDevices: daily.totalDevices, devicesOnline: daily.devicesOnline, devicesWithIssues: daily.devicesWithIssues, telemetry: daily.telemetry }, recommendation } };
